window.lspEnterEditMode=function(){
  var editBtn=document.getElementById('lspEditBtn');
  var saveBtn=document.getElementById('lspSaveBtn');
  var pubBtn=document.getElementById('lspPublishBtn');
  var banner=document.getElementById('lspDraftBanner');
  if(editBtn) editBtn.style.display='none';
  if(saveBtn) saveBtn.style.display='';
  if(pubBtn)  pubBtn.style.display='';
  if(banner)  banner.style.display='flex';
  document.body.classList.add('lsp-edit-mode');
  // Show all editor-only controls (Core Slides toolbar + card buttons)
  if(window.LSP_DATA && window.LSP_DATA.can_edit){
    document.querySelectorAll('.cd-editor-only,.lsp-editor-only').forEach(function(el){
      el.style.display='';
    });
  }
  // NEW JOB: auto-open config ONLY on first-ever load (never published, no saved config).
  // Uses localStorage keyed by job_id so it persists across refreshes.
  // Once user clicks Apply in config, tables are saved to localStorage and modal never auto-opens again.
  (function(){
    if(!(window.LSP_DATA && window.LSP_DATA.can_edit && !window.LSP_DATA.published_at)) return;
    var jobId = window.LSP_DATA.job_id || 'new';
    var _lsKey = 'lsp_cfg:' + jobId;
    // Restore previously saved config from localStorage into window vars
    try {
      var _saved = JSON.parse(localStorage.getItem(_lsKey) || 'null');
      if(_saved && _saved.overall) window._lspOverallCrsTable = _saved.overall;
      if(_saved && _saved.target) window._lspTargetCrsTable  = _saved.target;
    } catch(_){}
    // Only auto-open if no config saved yet for this job
    var hasConfig = !!(window._lspOverallCrsTable || window._lspTargetCrsTable);
    if(!hasConfig && typeof window.lspOpenTopConfig === 'function'){
      setTimeout(function(){
        var msg = document.getElementById('jobStatusMessage');
        if(msg){ msg.textContent = 'New job: please select CR tables in Config before publishing.'; msg.style.color='#d97706'; }
        window.lspOpenTopConfig();
      }, 400);
    }
  })();
};
// AUTO EDIT MODE: new draft jobs (never published) enter edit mode immediately
(function(){
  if(CAN_EDIT && !PUBLISHED_AT){
    document.addEventListener('DOMContentLoaded', function(){
      if(typeof window.lspEnterEditMode === 'function') window.lspEnterEditMode();
    });
    // fallback if DOMContentLoaded already fired
    if(document.readyState !== 'loading'){
      setTimeout(function(){ if(typeof window.lspEnterEditMode === 'function') window.lspEnterEditMode(); }, 100);
    }
  }
})();

function lspCollectDraftRows(){
  const src=(Array.isArray(window._rbSaved)&&(window._rbSaved.length||window._rbSavedHydrated))?window._rbSaved:(D.all_rows||[]);
  const rows=(src||[]).map(r=>({
    meta_id:r.meta_id||'',
    build_id:r.build_id||r.build_full||'',
    build_full:r.build_full||r.build_id||'',
    display_build:r.meta_id||r.build_id||'',
    domain:String(r.domain||'').toUpperCase(),
    deck_type:String(r.domain||'').toUpperCase(),
    deviceName:r.deviceName||r.device_name||'',
    product_flavor:r.product_flavor||r.deviceName||'',
    hours:r.hours||'',
    reduction:r.reduction||'',
    reduction_percent:r.reduction||'',
    crashes:r.crashes||'',
    device_count:r.device_count||'',
    published:!!r.published,
    publishedAt:r.publishedAt||'',
    run_status:r.run_status||'running',
    source:r.source||'json'
  })).filter(r=>r.build_full||r.meta_id);
  return rows;
}
window.lspSaveDraft=async function(){
  var target=(window.LSP_DATA||{}).primary_target||'';
  if(!target){alert('No target found.');return;}
  var statusEl=document.getElementById('jobStatusMessage');
  function setStatus(msg,err){
    console.log('[lspSaveDraft]',msg);
    if(statusEl){statusEl.textContent=msg;statusEl.style.color=err?'#b91c1c':'#16a34a';if(!err)setTimeout(function(){statusEl.textContent='';},3000);}
    else if(err){alert(msg);}
  }
  setStatus('Saving...');
  try{
    var r=await fetch('/api/live_status/targets/'+encodeURIComponent(target)+'/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rows:lspCollectDraftRows()})});
    var d=await r.json();
    if(!d.ok){setStatus(d.error||'Save failed',true);return;}
    setStatus('Saved \u2713');
    var eb=document.getElementById('lspEditBtn'),sb=document.getElementById('lspSaveBtn'),pb=document.getElementById('lspPublishBtn');
    if(eb)eb.style.display='none';
    if(sb)sb.style.display='';
    if(pb)pb.style.display='';
  }catch(e){setStatus('Save failed: '+e,true);}
};
window.lspPublishJob=async function(){
  var target=(window.LSP_DATA||{}).primary_target||'';
  if(!target){alert('No target found.');return;}
  var statusEl=document.getElementById('jobStatusMessage');
  function setStatus(msg,err){
    console.log('[lspPublishJob]',msg);
    if(statusEl){statusEl.textContent=msg;statusEl.style.color=err?'#b91c1c':'#16a34a';if(!err)setTimeout(function(){statusEl.textContent='';},3000);}
    else if(err){alert(msg);}
  }
  // MANDATORY CONFIG CHECK: block publish if no CR tables selected
  var isAuto = !!(window.LSP_DATA && window.LSP_DATA.is_auto_bu);
  if(!isAuto){
    var hasOverall = !!(window._lspOverallCrsTable && window._lspOverallCrsTable.trim());
    var hasTarget  = !!(window._lspTargetCrsTable  && window._lspTargetCrsTable.trim());
    if(!hasOverall || !hasTarget){
      var missing = [];
      if(!hasOverall) missing.push('Overall CR Table');
      if(!hasTarget)  missing.push('Target CR Table');
      setStatus('Config required before publish: ' + missing.join(', '), true);
      alert('Cannot publish yet.\n\nPlease select the following in Config (\u2699 button):\n\u2022 ' + missing.join('\n\u2022 ') + '\n\nClick the Config button (orange/red) in the header to set them.');
      if(typeof window.lspOpenTopConfig === 'function') window.lspOpenTopConfig();
      return;
    }
  }
  if(!confirm('Publish this report? Viewers will see it immediately.'))return;
  setStatus('Publishing...');
  try{
    await fetch('/api/live_status/targets/'+encodeURIComponent(target)+'/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rows:lspCollectDraftRows()})});
    var r=await fetch('/api/live_status/targets/'+encodeURIComponent(target)+'/publish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rows:lspCollectDraftRows()})});
    var d=await r.json();
    if(!d.ok){setStatus(d.error||'Publish failed',true);return;}
    setStatus('Published \u2713');
    setTimeout(function(){window.location.reload();},800);
  }catch(e){setStatus('Publish failed: '+e,true);}
};
