function applyCoreDeckConfigModal(){const ovSelect=String(($('cdCfgOverallCrsTable')||{}).value||'').trim();const ovManual=String(($('cdCfgOverallCrsManual')||{}).value||'').trim();const overall=ovManual||ovSelect;_cdOverallCrsTable=overall;for(const deck of ['IVI','FLEX','ADAS']){const txt=String(($('cdCfgJson'+deck)||{}).value||'').trim();if(txt){try{const parsed=JSON.parse(txt);const arr=Array.isArray(parsed)?parsed:[parsed];if(overall)arr.forEach(e=>{if(e&&typeof e==='object'&&!e.overallcrs_table&&!e.overall_crs_table)e.overallcrs_table=overall;});_cdDeckConfig[deck]=arr;continue;}catch(e){alert(deck+' DB/table JSON is invalid: '+e);return;}}const sel=$('cdCfg'+deck);const names=sel?[...sel.selectedOptions].map(o=>o.value):[];_cdDeckConfig[deck]=_cdCfgWrapTargetsWithOverall(names,overall)}const st=$('cdTopSaveStatus')||$('cdSaveStatus');if(st)st.textContent='Applied '+_cdConfigCountText()+(overall?' | OverallCRs '+overall:'');if(_cdConfigIsEmpty()){alert('Core Slides Config is empty. Select IVI/FLEX/ADAS targets/tables before Refresh/Save.');return;}closeCoreDeckConfigModal();refreshCoreDeckConfiguredTables();}
function ensureCoreDeckTableProgressModal(){let modal=$('cdTableProgressModal');if(modal)return modal;modal=document.createElement('div');modal.id='cdTableProgressModal';modal.className='wk-modal';modal.innerHTML='<div class="wk-modal-card" style="width:560px;max-width:92vw"><div class="wk-modal-head"><div><div id="cdTableProgressTitle" style="font-size:14px;font-weight:950;text-transform:uppercase;letter-spacing:.04em"><i class="fas fa-table"></i> Updating Core Slides Tables</div><div id="cdTableProgressSub" style="font-size:11px;color:#bfdbfe;margin-top:3px">Please wait. Do not refresh this page.</div></div></div><div style="padding:18px 20px;background:#f8fafc"><div id="cdTableProgressStep" style="font-weight:950;font-size:14px;color:#1e3a8a"></div><div id="cdTableProgressDetail" style="font-size:12px;font-weight:800;color:#334155;margin-top:6px;line-height:1.45"></div><div style="height:10px;background:#dbeafe;border-radius:999px;margin-top:14px;overflow:hidden"><div id="cdTableProgressBar" style="height:10px;width:5%;background:#2563eb;border-radius:999px;transition:width .25s"></div></div><div id="cdTableProgressElapsed" class="muted" style="font-size:11px;font-weight:900;margin-top:8px"></div></div></div>';document.body.appendChild(modal);return modal;}
function openCoreDeckTableProgress(title,sub){const modal=ensureCoreDeckTableProgressModal();_cdTableProgressStart=Date.now();const t=$('cdTableProgressTitle'),s=$('cdTableProgressSub');if(t)t.innerHTML='<i class="fas fa-table"></i> '+esc(title||'Updating Core Deck Tables');if(s)s.textContent=sub||'Please wait. Do not refresh this page.';modal.style.display='flex';updateCoreDeckTableProgress('Starting...', 'Preparing request', 5, false);}
function updateCoreDeckTableProgress(step,detail,pct,done){const modal=$('cdTableProgressModal');const st=$('cdTopSaveStatus')||$('cdSaveStatus');const icon=done?'<i class="fas fa-check-circle"></i>':'<i class="fas fa-circle-notch spin"></i>';if(st)st.innerHTML=`<span class="pill">${icon} ${esc(step)}</span>`+(pct!=null?` <span class="muted">${pct}%</span>`:'');if(!modal||modal.style.display==='none')return;const title=$('cdTableProgressStep'),det=$('cdTableProgressDetail'),bar=$('cdTableProgressBar'),el=$('cdTableProgressElapsed');if(title)title.innerHTML=icon+' '+esc(step||'Working...');if(det)det.textContent=detail||'';if(bar)bar.style.width=Math.max(5,Math.min(100,Number(pct||5)))+'%';if(el){const sec=Math.max(1,Math.round((Date.now()-(_cdTableProgressStart||Date.now()))/1000));el.textContent=(done?'Completed':'Running')+' | elapsed '+sec+'s';}}
function closeCoreDeckTableProgress(delay){const modal=$('cdTableProgressModal');if(!modal)return;setTimeout(()=>{modal.style.display='none'},delay==null?700:delay)}
