async function refreshCoreDeckConfiguredTables(){const st=$('cdTopSaveStatus')||$('cdSaveStatus');const t0=Date.now();openCoreDeckTableProgress('Refreshing Core Slides Tables','Loading DB pivots, weekly JIRA details and rebuilding slides.');try{updateCoreDeckTableProgress('Step 1/5: validating saved config','Checking IVI/FLEX/ADAS table config for this target',8,false);if(_cdConfigIsEmpty())await loadCoreDeckSavedConfig();if(_cdConfigIsEmpty()){const msg='Core Slides Config is empty. Open Config and select IVI/FLEX/ADAS tables first.';updateCoreDeckTableProgress('Config missing',msg,100,true);if(st)st.textContent=msg;alert(msg);closeCoreDeckTableProgress(1200);return;}const builds=_cdMetas.flatMap(m=>m.build_ids||[]);updateCoreDeckTableProgress('Step 2/5: reading selected builds',`${builds.length} build(s) selected. ${_cdConfigCountText()}`,18,false);await new Promise(r=>setTimeout(r,30));updateCoreDeckTableProgress('Step 3/5: loading CR pivots','Reading configured IVI/FLEX/ADAS DB/OpenJIRA/JIRA tables. This can take time.',35,false);await loadCoreDeckPreviewForBuilds();updateCoreDeckTableProgress('Step 4/5: loading weekly JIRA details','Fetching weekly details for selected builds.',68,false);if(builds.length)await loadCoreDeckWeeklyDetails(builds);updateCoreDeckTableProgress('Step 5/5: rendering updated slides','Rebuilding Core Deck tables in browser.',88,false);_cdTableDraftOverrides={};renderCoreDeckBuildList();renderCoreDeckSlides();updateCoreDeckTopBuildCount();const done='Tables refreshed '+new Date().toLocaleTimeString()+` (${Math.round((Date.now()-t0)/1000)}s) `+_cdConfigCountText();updateCoreDeckTableProgress('Tables refreshed',done,100,true);if(st)st.textContent=done;closeCoreDeckTableProgress(900);}catch(e){updateCoreDeckTableProgress('Table refresh failed',String(e),100,true);if(st)st.textContent=String(e);alert(String(e));closeCoreDeckTableProgress(1600);}}
function ensureCoreDeckBuildModal(){let modal=$('cdBuildModal');if(modal)return modal;modal=document.createElement('div');modal.id='cdBuildModal';modal.className='wk-modal';modal.innerHTML='<div class="wk-modal-card" style="width:94vw;max-width:1450px"><div class="wk-modal-head"><div><div style="font-size:14px;font-weight:950;text-transform:uppercase;letter-spacing:.04em"><i class="fas fa-vial"></i> Add Core Slide Builds</div><div style="font-size:11px;color:#bfdbfe;margin-top:3px">Build/flavor rows are loaded from SWPDT/Axiom. CR pivots are resolved from JIRA and OpenJIRA by same Meta.</div></div><button class="btn" onclick="closeCoreDeckBuildModal()"><i class="fas fa-times"></i></button></div><div style="display:flex;gap:10px;align-items:center;padding:12px 18px;border-bottom:1px solid #f1f5f9;background:#f8fafc;flex-wrap:wrap"><label style="font-size:12px;font-weight:950;color:#334155">Add to Slide</label><select id="cdBuildModalDeckType" class="compact-input" style="width:120px;height:32px;font-weight:950" onchange="if(document.getElementById(\'cdDeckTypeSelect\'))document.getElementById(\'cdDeckTypeSelect\').value=this.value;renderCoreDeckBuildModalList()"><option value="IVI">IVI</option><option value="FLEX">FLEX</option><option value="ADAS">ADAS</option></select><input id="cdBuildModalSearch" class="compact-input" style="flex:1;min-width:240px" placeholder="Search meta/build/flavor..." oninput="renderCoreDeckBuildModalList()"><button class="btn" onclick="coreDeckModalSelectVisible(true)">Select Visible</button><button class="btn" onclick="coreDeckModalSelectVisible(false)">Clear Visible</button><span id="cdBuildModalCount" class="muted" style="font-size:12px;font-weight:800"></span></div><div id="cdBuildModalList" class="wk-build-list"><div class="empty">Click Add Builds to load Axiom build/flavor rows.</div></div><div style="display:flex;justify-content:space-between;gap:10px;padding:14px 18px;border-top:1px solid #f1f5f9;background:#f8fafc;align-items:center"><span class="muted" style="font-size:12px;font-weight:800">Step 1: select build/flavour rows. Step 2 will show S.No, Product flavour, Builds and Alias name.</span><span><button class="btn" onclick="closeCoreDeckBuildModal()">Cancel</button> <button class="btn btn-primary" onclick="applyCoreDeckBuildModalSelection()"><i class="fas fa-arrow-right"></i> Save / Next</button></span></div></div>';document.body.appendChild(modal);return modal;}
function _metaFromBuildName(build){const leaf=String(build||'').split(/[\\/]/).filter(Boolean).pop()||String(build||'');let m=leaf.match(/meta[-_ ]?0*(\d{2,6})/i);if(m)return `Meta-${String(parseInt(m[1],10)).padStart(3,'0')}`;m=leaf.match(/-(\d{3,6})(?:\.\d+)?-(?:STD|PERF|SAFE|USER|ENG)/i);if(m)return `Meta-${String(parseInt(m[1],10)).padStart(3,'0')}`;const nums=[...leaf.matchAll(/-(\d{3,6})(?=-)/g)].map(x=>x[1]);if(nums.length)return `Meta-${String(parseInt(nums[nums.length-1],10)).padStart(3,'0')}`;return leaf.split(/[\s_\-.]+/).slice(0,2).join('-')||leaf;}
function _cdOptKey(o){if(typeof o==='string')return o;return [o.build_id||'',o.product_flavor||'',o.software_product||''].join('||')}
function _cdOptionBuild(o){return typeof o==='string'?o:(o.build_id||'')}
function _cdOptionFlavor(o){return typeof o==='string'?'':(o.product_flavor||'')}
function _cdShortFlavorAlias(flavor){const s=String(flavor||'').trim();if(!s)return'';const low=s.toLowerCase();const prefix=low.startsWith('nonsafe')?'nonsafe':(low.startsWith('safe')?'safe':'');let tail=s.includes('__')?s.split('__').pop():s;tail=tail.replace(/^_+/,'').replace(/[^A-Za-z0-9]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase();return prefix&&tail&&!tail.startsWith(prefix+'_')?`${prefix}_${tail}`:(tail||s)}
function _cdDefaultFlavorAlias(o){const short=_cdShortFlavorAlias(_cdOptionFlavor(o));return short||_leafBuildName(o.build_id)}
function removeCoreDeckFlavorPendingRow(key){_cdPendingFlavorRows=(_cdPendingFlavorRows||[]).filter(o=>_cdOptKey(o)!==key);_cdModalSelected.delete(key);_cdFlavorMergeKeys.delete(key);renderCoreDeckFlavorAliasTable();}
function toggleCoreDeckFlavorMergeRow(key,on){key=String(key||'');if(on)_cdFlavorMergeKeys.add(key);else _cdFlavorMergeKeys.delete(key);const cnt=$('cdFlavorMergeCount');if(cnt)cnt.textContent=_cdFlavorMergeKeys.size>=2?`${_cdFlavorMergeKeys.size} rows will be merged`:_cdFlavorMergeKeys.size===1?'Select at least 2 merge rows':'No row-level merge selected';}
function setCoreDeckFlavorMergeGroup(key,grp){key=String(key||'');if(!grp||grp==='none'){delete _cdFlavorMergeGroups[key];}else{_cdFlavorMergeGroups[key]=grp;}renderCoreDeckFlavorAliasTable();}window.setCoreDeckFlavorMergeGroup=setCoreDeckFlavorMergeGroup;
