async function loadCoreDeckJiraBuilds(){const resp=await fetch('/api/core_deck/build_options?'+new URLSearchParams({target:PRIMARY_TARGET,limit:'2000'}).toString());const data=await resp.json().catch(()=>({}));if(data.ok&&Array.isArray(data.build_options)&&data.build_options.length){_cdJiraBuilds=data.build_options;return _cdJiraBuilds;}throw new Error(data.error||'No build options returned from DB. Check axiom_job_summary table.');}
async function openCoreDeckBuildModal(){const modal=ensureCoreDeckBuildModal();modal.style.display='flex';const list=$('cdBuildModalList');if(list)list.innerHTML='<div class="empty"><i class="fas fa-circle-notch spin"></i> Loading Axiom build-flavor rows from DB...</div>';try{const modalType=$('cdBuildModalDeckType'),topType=$('cdDeckTypeSelect');if(modalType&&topType)modalType.value=topType.value||'IVI';if(!_cdJiraBuilds.length)await loadCoreDeckJiraBuilds();_cdModalSelected=new Set();renderCoreDeckBuildModalList();}catch(e){if(list)list.innerHTML=`<div class="empty">${esc(String(e))}</div>`}}
