function _deckBucketText(o){return (typeof o==='string'?o:[o.build_id,o.build_tail,o.software_product,o.product_flavor,o.deck_type].join(' ')).toUpperCase()}
function _guessDeckType(build){const s=_deckBucketText(build);if(/(^|[^A-Z0-9])ADAS([^A-Z0-9]|$)|ADP|RIDE|VISION|CAMERA/.test(s))return'ADAS';if(/(^|[^A-Z0-9])FLEX([^A-Z0-9]|$)|FLE/.test(s))return'FLEX';return'IVI'}
