function renderCoreDeckBuildModalList(){const list=$('cdBuildModalList');if(!list)return;const q=($('cdBuildModalSearch')?.value||'').toLowerCase();const targetSlide=String(($('cdBuildModalDeckType')||{}).value||'IVI').toUpperCase();const byDeck=(_cdJiraBuilds||[]).filter(o=>_cdModalDeckMatch(o,targetSlide));const items=byDeck.filter(o=>{const hay=[o.meta_id,o.build_id,o.build_tail,o.software_product,o.product_flavor,o.deck_type].join(' ').toLowerCase();return !q||hay.includes(q)});const cnt=$('cdBuildModalCount');if(cnt)cnt.textContent=`${_cdModalSelected.size} selected / ${items.length} shown / ${byDeck.length} ${targetSlide} rows / ${_cdJiraBuilds.length} total`;if(!items.length){list.innerHTML='<div class="empty">No matching '+esc(targetSlide)+' build/flavor rows.</div>';return;}list.innerHTML=items.map(o=>{const key=_cdOptKey(o),sel=_cdModalSelected.has(key),fl=o.product_flavor||'--';return `<label class="wk-build-row ${sel?'selected':''}" style="gap:10px;align-items:flex-start"><input type="checkbox" ${sel?'checked':''} onchange="toggleCoreDeckModalBuild(this.dataset.key,this.checked)" data-key="${_cdEscAttr(key)}"><span style="flex:1;min-width:0"><span style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><strong style="color:#1e3a8a">${esc(o.meta_id||_metaFromBuildName(o.build_id))}</strong><span class="pill" style="font-size:10px;padding:2px 7px">${esc(targetSlide)}</span><span class="pill good" style="font-size:10px;padding:2px 7px">${esc(fl)}</span><span class="muted" style="font-size:11px;font-weight:900">Jobs: ${esc(o.job_count||0)} Devices: ${esc(o.device_count||'--')}</span></span><span class="wk-build-name" style="display:block;word-break:break-all;margin-top:4px">${esc(o.build_id||'')}</span><span class="muted" style="font-size:11px;font-weight:800">${esc(o.software_product||'')} ${esc(o.latest_submitted||'')}</span></span></label>`}).join('')}
