async function loadCoreDeckWeeklyDetails(builds){const {from,to}=initWeeklyDates();const params=new URLSearchParams({from,to,target:PRIMARY_TARGET,force:'1',builds:(builds||[]).join(',')});const resp=await fetch(`/api/live_status/targets/${encodeURIComponent(PRIMARY_TARGET)}/weekly_full?${params.toString()}`);const data=await resp.json().catch(()=>({}));if(!data.success)throw new Error(data.message||'Failed to load CR/JIRA details');_cdWeeklyDetails=data;return data}
async function loadCoreDeckPreviewForBuilds(extraBuilds){const selectedMetas=_cdMetas.map(m=>({meta_id:m.meta_id,alias:m.alias||m.meta_id,build_ids:m.build_ids||[],product_flavors:m.product_flavors||[],flavor_builds:m.flavor_builds||[],merge_mode:m.merge_mode||'',deck_type:m.deck_type||'IVI'}));const known=new Set(selectedMetas.flatMap(m=>m.build_ids||[]).map(String));(extraBuilds||[]).filter(Boolean).forEach(b=>{if(known.has(String(b)))return;const meta=_metaFromBuildName(b);selectedMetas.push({meta_id:meta,alias:meta,build_ids:[b],product_flavors:[],flavor_builds:[],merge_mode:'pivot_only',deck_type:_guessDeckType(b)});known.add(String(b))});if(!selectedMetas.length){_cdCorePreview=null;return null}const resp=await fetch('/api/core_deck/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target:PRIMARY_TARGET,selected_metas:selectedMetas,deck_config:_cdDeckConfigWithOverall(),exec_summary:[]})});const data=await resp.json().catch(()=>({}));if(data.ok)_cdCorePreview=data;return data}
