    /* Build per-group row lists */
    const groups={};rows.forEach(x=>{const k=_cdOptKey(x);const g=groupMap[k];if(g){if(!groups[g])groups[g]=[];groups[g].push(x);}});
    const groupedKeys=new Set(Object.values(groupMap).length?Object.keys(groupMap):[]);
    /* Add each group as a merged row */
