function _cdStateMetaText(state){state=state||{};const subBy=state.submitted_by||state.created_by||'-',subAt=state.submitted_at||state.created_at||'-',modBy=state.last_modified_by||state.updated_by||'-',modAt=state.last_modified_at||state.updated_at||'-';return `Submitted by ${subBy} at ${subAt} | Last edited by ${modBy} at ${modAt}`}
