/* -- table row/col controls: single ... button -> dropdown menu -- */
var _cdOpenMenu=null;
function _cdCloseOpenMenu(){if(_cdOpenMenu){_cdOpenMenu.remove();_cdOpenMenu=null;}}
/* Use bubbling (not capture) so btn.onclick fires BEFORE the document close handler */
document.addEventListener('click',function(e){
  if(_cdOpenMenu&&!_cdOpenMenu.contains(e.target))_cdCloseOpenMenu();
});
function _cdMakeMenu(items){
  var menu=document.createElement('div');
  menu.style.cssText='position:fixed;z-index:999999;background:#fff;border:1.5px solid #93c5fd;border-radius:9px;box-shadow:0 8px 24px rgba(37,99,235,.22);padding:5px 0;min-width:180px;font-size:13px;';
  items.forEach(function(item){
    if(item==='-'){var sep=document.createElement('div');sep.style.cssText='height:1px;background:#e2e8f0;margin:4px 0;';menu.appendChild(sep);return;}
    var row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:10px;padding:8px 16px;cursor:pointer;color:'+(item.color||'#1e293b')+';font-weight:700;white-space:nowrap;border-radius:6px;margin:0 4px;';
    row.innerHTML='<span style="font-size:14px;width:18px;text-align:center;flex-shrink:0">'+item.icon+'</span><span>'+item.label+'</span>';
    row.onmouseenter=function(){row.style.background='#eff6ff';};
    row.onmouseleave=function(){row.style.background='';};
    row.onclick=function(e){e.stopPropagation();_cdCloseOpenMenu();item.action();};
    menu.appendChild(row);
  });
  return menu;
}
function _cdShowMenu(menu,anchorEl){
  _cdCloseOpenMenu();
  /* append first so offsetWidth/Height are real */
  menu.style.visibility='hidden';
  document.body.appendChild(menu);
  _cdOpenMenu=menu;
  var r=anchorEl.getBoundingClientRect();
  var mw=menu.offsetWidth,mh=menu.offsetHeight;
  var left=r.right+6,top=r.top;
  if(left+mw>window.innerWidth-8)left=r.left-mw-6;
  if(left<4)left=4;
  if(top+mh>window.innerHeight-8)top=window.innerHeight-mh-8;
  if(top<4)top=4;
  menu.style.left=left+'px';menu.style.top=top+'px';
  menu.style.visibility='visible';
}
function _cdMakeTriggerBtn(title){
  var btn=document.createElement('button');
  btn.type='button';
  btn.innerHTML='&#8942;'; /* vertical ellipsis ⋮ */
  btn.title=title||'Options';
  btn.style.cssText='border:1.5px solid #93c5fd;background:#dbeafe;color:#1d4ed8;border-radius:5px;padding:1px 6px;font-size:14px;font-weight:900;cursor:pointer;line-height:1.4;opacity:0;transition:opacity .12s;pointer-events:auto;display:inline-block;vertical-align:middle;';
  return btn;
}
function _cdAttachTableRowControls(tbl,key){
  var body=tbl.tBodies[0];if(!body)return;
  Array.from(body.rows).forEach(function(tr){
    if(tr._cdRowCtrlBound)return;tr._cdRowCtrlBound=true;
    /* inject a fixed-width control cell at the end of the row */
    var td=document.createElement('td');
    td.style.cssText='width:26px;min-width:26px;max-width:26px;padding:2px 3px!important;border:1px solid #e2e8f0!important;background:#f8fafc!important;vertical-align:middle;text-align:center;';
    td.setAttribute('data-cd-ctrl','1');
    var btn=_cdMakeTriggerBtn('Row options');
    btn.onclick=function(e){
      e.stopPropagation();
      if(!_cdSlideEditMode||!CAN_EDIT)return;
      var menu=_cdMakeMenu([
        {icon:'+',label:'Insert row above',color:'#1d4ed8',action:function(){addCoreDeckTableRow(key,tr,'above');}},
        {icon:'+',label:'Insert row below',color:'#059669',action:function(){addCoreDeckTableRow(key,tr,'below');}},
        '-',
        {icon:'&#x2715;',label:'Delete this row',color:'#dc2626',action:function(){if(body.rows.length<=1&&!confirm('Delete the last row?'))return;removeCoreDeckTableRow(key,tr);}}
      ]);
      _cdShowMenu(menu,btn);
    };
    td.appendChild(btn);
    tr.appendChild(td);
    /* show/hide on row hover - use relatedTarget to avoid flicker when moving to btn */
    tr.addEventListener('mouseenter',function(){if(_cdSlideEditMode&&CAN_EDIT)btn.style.opacity='1';});
    tr.addEventListener('mouseleave',function(e){
      var to=e.relatedTarget;
      if(to&&(td.contains(to)||btn===to))return;
      btn.style.opacity='0';
    });
  });
}
function _cdAttachTableColControls(tbl,key){
  var head=tbl.tHead;if(!head||!head.rows[0])return;
  /* also add a header cell above the row-ctrl column if row controls exist */
  Array.from(head.rows[0].cells).forEach(function(th,ci){
    if(th._cdColCtrlBound)return;th._cdColCtrlBound=true;
    th.style.position='relative';
    var btn=_cdMakeTriggerBtn('Column options');
    btn.style.cssText+=';position:absolute;top:3px;right:3px;';
    btn.onclick=function(e){
      e.stopPropagation();
      if(!_cdSlideEditMode||!CAN_EDIT)return;
      var menu=_cdMakeMenu([
        {icon:'&#8592;',label:'Insert col left',color:'#7c3aed',action:function(){addCoreDeckTableColumn(key,ci,'left');}},
        {icon:'&#8594;',label:'Insert col right',color:'#0e7490',action:function(){addCoreDeckTableColumn(key,ci,'right');}},
        '-',
        {icon:'&#x2715;',label:'Delete this col',color:'#dc2626',action:function(){var t=Array.from(tbl.rows).reduce(function(m,r){return Math.max(m,r.cells.length);},0);if(t<=1&&!confirm('Delete the last column?'))return;removeCoreDeckTableColumn(key,ci);}}
      ]);
      _cdShowMenu(menu,btn);
    };
    th.appendChild(btn);
    th.addEventListener('mouseenter',function(){if(_cdSlideEditMode&&CAN_EDIT)btn.style.opacity='1';});
    th.addEventListener('mouseleave',function(e){
      var to=e.relatedTarget;
      if(to&&(th.contains(to)||btn===to))return;
      btn.style.opacity='0';
    });
  });
}
