function _cdCrashTotalsFromText(text){const out={system:0,ssr:0,process:0,open:0};String(text||'').split(/\n+/).forEach(line=>{const m=String(line||'').match(/^([^\-]+)--\s*(\d+)/);if(!m)return;const label=m[1].toLowerCase();const n=Number(m[2]||0)||0;if(label.includes('process'))out.process+=n;else if(label.includes('ssr'))out.ssr+=n;else if(label.includes('open'))out.open+=n;else if(label.includes('system'))out.system+=n;});return out}
