function _cdCrashTotalsHtml(t){t=t||{};const total=(Number(t.system||0)+Number(t.ssr||0)+Number(t.process||0));const pills=[];if(Number(t.system||0)>0)pills.push(`<span style="background:#e8f3ff;color:#155e91;border:1px solid #93c5fd;border-radius:999px;padding:1px 7px;font-weight:950">System: ${esc(t.system)}</span>`);if(Number(t.ssr||0)>0)pills.push(`<span style="background:#fff7e6;color:#b45309;border:1px solid #fbbf24;border-radius:999px;padding:1px 7px;font-weight:950">SSR: ${esc(t.ssr)}</span>`);if(Number(t.process||0)>0)pills.push(`<span style="background:#fef2f2;color:#b91c1c;border:1px solid #fca5a5;border-radius:999px;padding:1px 7px;font-weight:950">Process: ${esc(t.process)}</span>`);if(Number(t.open||0)>0)pills.push(`<span style="background:#eefdf3;color:#15803d;border:1px solid #86efac;border-radius:999px;padding:1px 7px;font-weight:950">Open JIRA (not CR converted): ${esc(t.open)}</span>`);if(!pills.length)pills.push('<span style="font-weight:950;color:#64748b">No CR-converted crashes</span>');return `<div style="display:flex;gap:5px;flex-wrap:wrap;align-items:center;justify-content:flex-start;font-size:11px;line-height:1.2"><span style="font-weight:950;color:#111827;margin-right:3px">Total:</span>${pills.join('')}</div>`}
function _cdDefaultExecSummaryHtml(type,builds,topSource,totalBreakdown,totalJira,totalCrs){const top=(topSource||[]).filter(r=>_cdIsRealCr(r.cr)).slice(0,2);const hitter=top.length?top.map(r=>`${esc(_cdNormCrDisplay(r.cr)||r.cr)} (${esc(r.count||0)}) - ${esc(String(r.title||'').slice(0,95)||'--')}`).join('</li><li>'):'No current-build high hitter CRs identified.';const tb=totalBreakdown||{};const crashTotal=(Number(tb.system||0)+Number(tb.ssr||0)+Number(tb.process||0));const parts=[];if(Number(tb.system||0)>0)parts.push(`System ${esc(tb.system)}`);if(Number(tb.ssr||0)>0)parts.push(`SSR ${esc(tb.ssr)}`);if(Number(tb.process||0)>0)parts.push(`Process ${esc(tb.process)}`);const splitText=parts.length?`${parts.join(', ')}; total crashes ${esc(crashTotal)}`:'No System/SSR/Process crashes observed.';return `<ul style="font-size:16px;line-height:1.55;margin:0 0 0 18px;padding-left:12px"><li>${esc(type)} validation covered ${esc(builds.length)} selected build/flavour row(s); total JIRAs ${esc(totalJira||0)}, total CRs ${esc(totalCrs||0)}.</li><li>Crash split: ${splitText}</li><li>Top high hitter CRs:<ul style="margin:3px 0 0 18px;padding-left:10px"><li>${hitter}</li></ul></li><li><b>Engineer summary:</b> Click <b>Edit Slides</b> and replace below with 2-3 short points:<ul style="margin:3px 0 0 18px;padding-left:10px"><li>Point 1 - current blocker / observation.</li><li>Point 2 - debug status / owner / next step.</li><li>Point 3 - risk, ETA, or closure plan if applicable.</li></ul></li></ul>`}
