function _cdBackendFlavorPivot(x){
  const build=String(x.build||'');
  const flavor=String(x.flavor||'');
  const pivots=((_cdCorePreview||{}).flavor_job_pivots)||{};
  /* 1. Exact key */
  const key=build+'||'+flavor;
  if(pivots[key]){const fp=pivots[key];fp.__ctx_key=key;return fp;}
  /* 2. Joined flavor - try each individual part */
  if(flavor.includes(' + ')){
    const parts=flavor.split(/\s*\+\s*/).map(p=>p.trim()).filter(Boolean);
    const fps=parts.map(p=>{const k=build+'||'+p;return pivots[k]?{...pivots[k],__ctx_key:k}:null;}).filter(Boolean);
    if(fps.length===1)return fps[0];
    if(fps.length>1){
      const ctx=fps.map(fp=>fp.__ctx_key).join('~~');
      return {__ctx_key:ctx,
        crashes:fps.reduce((s,fp)=>s+Number(fp.crashes||0),0),
        display_text:fps.map(fp=>String(fp.display_text||'').trim()).filter(Boolean).join('\n'),
        occurrence_rows:fps.flatMap(fp=>Array.isArray(fp.occurrence_rows)?fp.occurrence_rows:[])};
    }
  }
  return null;
}
function _cdBackendFlavorPivotForRow(x){
  const builds=(Array.isArray(x&&x.builds)&&x.builds.length?x.builds:[x&&x.build]).filter(Boolean);
  if(builds.length<=1)return _cdBackendFlavorPivot(Object.assign({},x,{build:builds[0],flavor:(x&&x.flavor)||_cdFlavor(builds[0])}));
  /* Multi-build merged row: expand via flavor_builds to get exact build||flavor pairs */
  const flavorBuilds=Array.isArray(x&&x.flavor_builds)?x.flavor_builds:[];
  const pairs=[];
  if(flavorBuilds.length){
    flavorBuilds.forEach(fb=>{
      const b=String(fb.build_id||'');const f=String(fb.product_flavor||'');
      if(b)pairs.push({build:b,flavor:f});
    });
  } else {
    builds.forEach(b=>pairs.push({build:b,flavor:_cdFlavor(b)}));
  }
  const fps=pairs.map(p=>_cdBackendFlavorPivot(p)).filter(Boolean);
  if(!fps.length)return null;
  const ctx=fps.map(fp=>fp.__ctx_key).filter(Boolean).join('~~');
  return {__ctx_key:ctx,
    crashes:fps.reduce((sum,fp)=>sum+Number(fp.crashes||0),0),
    display_text:fps.map(fp=>String(fp.display_text||'').trim()).filter(Boolean).join('\n'),
    occurrence_rows:fps.flatMap(fp=>Array.isArray(fp.occurrence_rows)?fp.occurrence_rows:[])};
}
